function nextDashboard({ values, previousState }) {
  if (!Array.isArray(values)) throw Error("Invalid dashboard");
  const index = previousState?.index ?? 0;
  if (!Number.isInteger(index) || index < 0) throw Error("Invalid index");
  if (!values.length)
    return { state: { index }, more: false, url: "https://unused.invalid", site: {}, count: index };
  const head = values[0];
  if (
    !Array.isArray(head) ||
    ["Property", "Status", "Log Sheet"].some((x) => head.filter((v) => v === x).length !== 1)
  )
    throw Error("Dashboard requires unique Property, Status and Log Sheet headers");
  const p = head.indexOf("Property"),
    s = head.indexOf("Status"),
    l = head.indexOf("Log Sheet");
  const rows = values
    .slice(1)
    .map((v, i) => ({ v, row: i + 2 }))
    .filter((x) => Array.isArray(x.v) && x.v.some((y) => y !== "" && y != null));
  const seen = new Set();
  for (const { v } of rows) {
    if (
      typeof v[p] !== "string" ||
      !/^https?:\/\//i.test(v[p]) ||
      /[\r\n]/.test(v[p]) ||
      seen.has(v[p])
    )
      throw Error("Invalid or duplicate Property");
    seen.add(v[p]);
    if (!["UP", "DOWN"].includes(v[s])) throw Error("Invalid Status");
    if (typeof v[l] !== "string" || !v[l].trim() || /[\[\]*?:/\\]/.test(v[l]))
      throw Error("Invalid Log Sheet");
  }
  if (index >= rows.length)
    return { state: { index }, more: false, url: "https://unused.invalid", site: {}, count: index };
  const x = rows[index];
  return {
    state: { index: index + 1 },
    more: true,
    url: x.v[p],
    site: { property: x.v[p], status: x.v[s], logSheet: x.v[l], row: x.row, statusColumn: s },
    count: index + 1,
  };
}

const values = $input.first().json.values ?? [];
let previousState = null,
  out = [];
while (true) {
  const x = nextDashboard({ values, previousState });
  if (!x.more) break;
  out.push({ json: x.site, pairedItem: { item: 0 } });
  previousState = x.state;
}
return out;

function dashboardFields({ site, up, now }) {
  if (
    !site ||
    typeof site.property !== "string" ||
    !["UP", "DOWN"].includes(site.status) ||
    typeof site.logSheet !== "string" ||
    !Number.isInteger(site.row) ||
    !Number.isInteger(site.statusColumn) ||
    typeof up !== "boolean"
  )
    throw Error("Invalid site");
  const time = new Date(now);
  if (Number.isNaN(time.getTime())) throw Error("Invalid time");
  const stamp = time.toISOString(),
    status = up ? "UP" : "DOWN",
    event = `${status}_FROM_${site.status}`,
    quote = (x) => "'" + x.replaceAll("'", "''") + "'";
  let col = site.statusColumn + 1,
    label = "";
  while (col) {
    col--;
    label = String.fromCharCode(65 + (col % 26)) + label;
    col = Math.floor(col / 26);
  }
  const message = `From: n8n uptime\nDate: ${stamp}\n\n${site.property} is ${status}`;
  return {
    logRange: quote(site.logSheet) + "!A:G",
    logValues: [
      [
        stamp,
        stamp.slice(0, 7),
        site.property,
        event === "UP_FROM_UP",
        event === "DOWN_FROM_DOWN",
        event === "UP_FROM_DOWN",
        event === "DOWN_FROM_UP",
      ],
    ],
    statusRange: `'dashboard'!${label}${site.row}`,
    statusValues: [[status]],
    alert: event !== "UP_FROM_UP",
    subject: `n8n uptime: ${site.property} is ${status}`,
    message,
  };
}

const x = $input.first().json,
  site = $("Check one site at a time").item.json;
if (!Number.isInteger(x.statusCode) || x.statusCode < 100 || x.statusCode > 599)
  throw Error("Invalid HTTP status");
return [
  {
    json: dashboardFields({ site, up: x.statusCode < 400, now: $now.toISO() }),
    pairedItem: { item: 0 },
  },
];

function confirm({ updatedCells }) {
  if (updatedCells !== 1) throw Error("Status update was not confirmed");
  return { ok: true };
}

return [
  { json: confirm({ updatedCells: $input.first().json.updatedCells }), pairedItem: { item: 0 } },
];
